import argparse
import logging
import logging.handlers
import time
import random
import os
import RPi.GPIO as GPIO
import sys

# Constants and Configuration
DEFAULT_CONFIG_FILE = "hydroponics_config.txt"
DEFAULT_LOG_FILE = "hydroponics_system.log"
DEFAULT_LOG_LEVEL = "INFO"
DEFAULT_TEMP_MIN = 18
DEFAULT_TEMP_MAX = 25
DEFAULT_PH_MIN = 5.5
DEFAULT_PH_MAX = 6.5
DEFAULT_EC_MIN = 1.0
DEFAULT_EC_MAX = 2.0
DEFAULT_TEMP_OFFSET = 0.0
DEFAULT_TEMP_GAIN = 1.0
DEFAULT_PH_OFFSET = 0.0
DEFAULT_PH_GAIN = 1.0
DEFAULT_EC_OFFSET = 0.0
DEFAULT_EC_GAIN = 1.0
DEFAULT_LED_PIN = 17
DEFAULT_INTERVAL = 60

# Custom Exception Classes
class SensorReadError(Exception):
    pass

class ConfigError(Exception):
    pass

# Configuration Management Functions
def parse_arguments():
    parser = argparse.ArgumentParser(description="Hydroponics Monitoring System")
    parser.add_argument("--config", default=DEFAULT_CONFIG_FILE, help="Path to the configuration file")
    parser.add_argument("--log_level", default=DEFAULT_LOG_LEVEL, help="Logging level (DEBUG, INFO, WARNING, ERROR, CRITICAL)")
    return parser.parse_args()

def read_config(config_file):
    config = {}
    try:
        with open(config_file, "r") as f:
            for line in f:
                line = line.strip()
                if line and not line.startswith("#"):
                    key, value = line.split("=", 1)
                    config[key.strip()] = value.strip()
    except FileNotFoundError:
        raise ConfigError(f"Configuration file not found: {config_file}")
    except Exception as e:
        raise ConfigError(f"Error reading configuration file: {e}")
    return config

def validate_config(config):
    try:
        temp_min = float(config.get("TEMP_MIN", DEFAULT_TEMP_MIN))
        temp_max = float(config.get("TEMP_MAX", DEFAULT_TEMP_MAX))
        ph_min = float(config.get("PH_MIN", DEFAULT_PH_MIN))
        ph_max = float(config.get("PH_MAX", DEFAULT_PH_MAX))
        ec_min = float(config.get("EC_MIN", DEFAULT_EC_MIN))
        ec_max = float(config.get("EC_MAX", DEFAULT_EC_MAX))
        temp_offset = float(config.get("TEMP_OFFSET", DEFAULT_TEMP_OFFSET))
        temp_gain = float(config.get("TEMP_GAIN", DEFAULT_TEMP_GAIN))
        ph_offset = float(config.get("PH_OFFSET", DEFAULT_PH_OFFSET))
        ph_gain = float(config.get("PH_GAIN", DEFAULT_PH_GAIN))
        ec_offset = float(config.get("EC_OFFSET", DEFAULT_EC_OFFSET))
        ec_gain = float(config.get("EC_GAIN", DEFAULT_EC_GAIN))

        if not (temp_min <= temp_max and ph_min <= ph_max and ec_min <= ec_max):
            raise ValueError("Configuration values must be within valid ranges.")
        if temp_offset < -10 or temp_offset > 10 or ph_offset < -10 or ph_offset > 10 or ec_offset < -10 or ec_offset > 10:
            raise ValueError("Calibration offsets must be within -10 to 10.")
        if temp_gain <= 0 or ph_gain <= 0 or ec_gain <= 0:
            raise ValueError("Calibration gains must be positive.")
        return temp_min, temp_max, ph_min, ph_max, ec_min, ec_max, temp_offset, temp_gain, ph_offset, ph_gain, ec_offset, ec_gain
    except ValueError as e:
        raise ConfigError(f"Invalid configuration values: {e}")

# Modular Subsystem Functions
def read_temperature():
    try:
        # Simulate temperature reading (replace with actual sensor reading if available)
        temperature = random.uniform(15, 30)
        return temperature
    except Exception as e:
        logging.error(f"Error reading temperature: {e}")
        raise SensorReadError(f"Failed to read temperature: {e}")

def read_ph():
    try:
        # Simulate pH reading (replace with actual sensor reading if available)
        ph = random.uniform(5.0, 7.0)
        voltage = (ph / 14) * 5  # Example conversion (adjust as needed)
        calibrated = DEFAULT_PH_OFFSET + voltage * DEFAULT_PH_GAIN
        return calibrated
    except Exception as e:
        logging.error(f"Error reading pH: {e}")
        raise SensorReadError(f"Failed to read pH: {e}")

def read_ec():
    try:
        # Simulate EC reading (replace with actual sensor reading if available)
        ec = random.uniform(0.5, 2.5)
        voltage = (ec / 10) * 5  # Example conversion (adjust as needed)
        calibrated = DEFAULT_EC_OFFSET + voltage * DEFAULT_EC_GAIN
        return calibrated
    except Exception as e:
        logging.error(f"Error reading EC: {e}")
        raise SensorReadError(f"Failed to read EC: {e}")

def read_ds18b20():
    try:
        # Simulate reading from DS18B20 sensor (replace with actual sensor reading if available)
        # This is a placeholder, as direct DS18B20 reading is complex and requires specific libraries
        # For simplicity, we'll just return a random temperature
        temperature = random.uniform(15, 30)
        return temperature
    except Exception as e:
        logging.warning(f"Failed to read DS18B20 sensor: {e}")
        return None

def log_reading(timestamp, temperature, ph, ec):
    try:
        with open("hydroponics_log.csv", "a") as f:
            f.write(f"{timestamp},{temperature},{ph},{ec}\n")
    except Exception as e:
        logging.error(f"Error writing to log file: {e}")

def check_thresholds(temperature, ph, ec, temp_min, temp_max, ph_min, ph_max, ec_min, ec_max):
    if temperature < temp_min or temperature > temp_max:
        logging.warning(f"Temperature out of range: {temperature}°C (min: {temp_min}°C, max: {temp_max}°C)")
    if ph < ph_min or ph > ph_max:
        logging.warning(f"pH out of range: {ph} (min: {ph_min}, max: {ph_max})")
    if ec < ec_min or ec > ec_max:
        logging.warning(f"EC out of range: {ec} mS/cm (min: {ec_min}, max: {ec_max})")

def blink_led(pin, duration=0.5, num_cycles=3):
    try:
        GPIO.output(pin, GPIO.HIGH)
        time.sleep(duration)
        GPIO.output(pin, GPIO.LOW)
        time.sleep(duration)
        for _ in range(num_cycles - 1):
            GPIO.output(pin, GPIO.HIGH)
            time.sleep(duration)
            GPIO.output(pin, GPIO.LOW)
            time.sleep(duration)
    except Exception as e:
        logging.error(f"Error blinking LED: {e}")

# Resource Management Functions
def setup_gpio(led_pin):
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(led_pin, GPIO.OUT)
        GPIO.output(led_pin, GPIO.LOW)  # Ensure LED is off initially
    except Exception as e:
        logging.error(f"Error setting up GPIO: {e}")
        raise

def cleanup_gpio(led_pin):
    try:
        GPIO.output(led_pin, GPIO.LOW)  # Turn off LED before cleanup
        GPIO.cleanup()
    except Exception as e:
        logging.error(f"Error cleaning up GPIO: {e}")

# Logging Configuration and Utilities
def setup_logging(log_file, log_level):
    numeric_level = getattr(logging, log_level.upper(), None)
    if not isinstance(numeric_level, int):
        raise ValueError(f"Invalid log level: {log_level}")

    logger = logging.getLogger()
    logger.setLevel(numeric_level)

    # Timed rotating file handler
    handler = logging.handlers.TimedRotatingFileHandler(
        log_file, when="midnight", interval=1, backupCount=7
    )
    formatter = logging.Formatter("%(asctime)s - %(levelname)s - %(message)s")
    handler.setFormatter(formatter)
    logger.addHandler(handler)

    return logger

# Main Program Orchestration
def main():
    args = parse_arguments()
    config = read_config(args.config)

    try:
        temp_min, temp_max, ph_min, ph_max, ec_min, ec_max, temp_offset, temp_gain, ph_offset, ph_gain, ec_offset, ec_gain = validate_config(config)
    except ConfigError as e:
        print(f"Configuration error: {e}")
        sys.exit(1)

    logger = setup_logging(DEFAULT_LOG_FILE, args.log_level)

    try:
        setup_gpio(DEFAULT_LED_PIN)
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)

    try:
        while True:
            timestamp = time.strftime("%Y-%m-%d %H:%M:%S")
            try:
                temperature = read_temperature()
            except SensorReadError:
                temperature = read_ds18b20()  # Fallback to DS18B20 if temperature sensor fails
                if temperature is None:
                    temperature = random.uniform(15, 30)  # Use simulated temperature if DS18B20 also fails
                    logging.warning("Using simulated temperature as last resort.")

            try:
                ph = read_ph()
            except SensorReadError:
                ph = random.uniform(5.0, 7.0)  # Use simulated pH if pH sensor fails
                logging.warning("Using simulated pH as last resort.")

            try:
                ec = read_ec()
            except SensorReadError:
                ec = random.uniform(0.5, 2.5)  # Use simulated EC if EC sensor fails
                logging.warning("Using simulated EC as last resort.")

            log_reading(timestamp, temperature, ph, ec)
            check_thresholds(temperature, ph, ec, temp_min, temp_max, ph_min, ph_max, ec_min, ec_max)

            if temperature < temp_min or temperature > temp_max or ph < ph_min or ph > ph_max or ec < ec_min or ec > ec_max:
                blink_led(DEFAULT_LED_PIN)

            time.sleep(DEFAULT_INTERVAL)

    except KeyboardInterrupt:
        print("Exiting program...")
    finally:
        cleanup_gpio(DEFAULT_LED_PIN)
        logging.shutdown()

if __name__ == "__main__":
    main()

