import time
import numpy
from picamera2 import Picamera2

# Motion detection settings
MOTION_THRESHOLD = 10
FRAME_INTERVAL = 2

def initialize_camera():
    """Initialize the Raspberry Pi camera."""
    try:
        camera = Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        time.sleep(2)  # Allow camera to warm up
        return camera
    except Exception as e:
        print(f"Error initializing camera: {e}")
        return None

def capture_baseline(camera):
    """Capture the initial frame and calculate its average pixel value."""
    try:
        baseline_frame = camera.capture_array()
        baseline_average = numpy.mean(baseline_frame)
        return baseline_average
    except Exception as e:
        print(f"Error capturing baseline: {e}")
        return None

def detect_motion(camera, baseline_average):
    """Capture a frame, compare it to the baseline, and return True if motion is detected."""
    try:
        current_frame = camera.capture_array()
        current_average = numpy.mean(current_frame)
        difference = abs(current_average - baseline_average)
        return difference > MOTION_THRESHOLD
    except Exception as e:
        print(f"Error detecting motion: {e}")
        return False

def save_image(camera):
    """Capture and save an image when motion is detected."""
    try:
        camera.capture_file("motion.jpg")
        print("Image saved!")
    except Exception as e:
        print(f"Error saving image: {e}")

def main():
    """Main function to run the motion detection loop."""
    camera = initialize_camera()
    if camera is None:
        return

    baseline_average = capture_baseline(camera)
    if baseline_average is None:
        camera.close()
        return

    try:
        while True:
            if detect_motion(camera, baseline_average):
                print("Motion detected!")
                save_image(camera)
                baseline_average = numpy.mean(camera.capture_array()) # Update baseline to current frame
            time.sleep(FRAME_INTERVAL)
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        camera.close()

if __name__ == "__main__":
    main()

