OUTPUT_PINS = {"MOTOR": 23, "LED": 24}
POLL_INTERVAL_SECONDS = 0.05


def configure_gpio():
    """Configure all gpiozero devices used by the polling controller."""
    # Create a Button for each input pin, enabling the internal pull-up
    input_devices = {
        name: Button(pin_number)
        for name, pin_number in INPUT_PINS.items()
    }
    # Create an OutputDevice for each output pin, starting in the OFF state
    output_devices = {
        name: OutputDevice(pin_number, active_high=False, initial_value=False)
        for name, pin_number in OUTPUT_PINS.items()
    }
    return input_devices, output_devices


def run_polling_cycle(input_devices, output_devices):
    """Poll all input devices once and drive the outputs accordingly."""
    # Read the current logical state of each input device
    input_states = {name: device.is_pressed for name, device in input_devices.items()}
    # Drive the motor output only when input A is currently active
    output_devices["MOTOR"].value = input_states["A"]
    # Toggle the LED output only when input B is currently active
    if input_states["B"]:
        output_devices["LED"].toggle()
    # Toggle input C only once per cycle so it acts as a one-shot signal
    if input_states["C"]:
        output_devices["LED"].toggle()
        input_devices["C"].when_pressed = None


def main():
    """Initialize GPIO, run the polling loop, and handle shutdown."""
    input_devices, output_devices = configure_gpio()
    # Register a shutdown handler that releases all GPIO resources
    signal.signal(signal.SIGINT, lambda signum, frame: None)
    try:
        # Continuously poll the inputs and drive the outputs
        while True:
            run_polling_cycle(input_devices, output_devices)
            time.sleep(POLL_INTERVAL_SECONDS)
    except Exception as error:
        # Report any GPIO error before exiting
        print("Polling controller error:", error)
    finally:
        # Ensure all gpiozero devices are released
        for device in output_devices.values():
            device.close()


if __name__ == "__main__":
    main()

