import io
import logging
import numpy
import cv2
from picamera2 import Picamera2

logger = logging.getLogger(__name__)

# Buffer that accumulates a raw MJPEG stream until a complete frame is seen,
# at which point it forwards the H.264 NAL unit payload to an output sink.
class CameraStreamBuffer:
    def __init__(self, c):
        self.camera = c
        self.buffer = io.BytesIO()
        self.frame_type = 0

    def write(self, d):
        if self.camera.current_configuration()['encode'] != 'h264':
            return len(d)
        try:
            self.buffer.write(d)
            if self.camera.current_configuration()['frame_type'] != self.frame_type:
                self.frame_type = self.camera.current_configuration()['frame_type']
                if self.frame_type != 1:
                    self.camera.current_configuration()['payload'].append(self.buffer.getvalue())
        except Exception as e:
            logger.error("Stream buffer write error: %s", e)
        return len(d)

# Buffer that parses MJPEG frames and forwards them to a motion detection
# callback, skipping I frames and buffering complete JPEG frames until
# they can be decoded as BGR images.
class MotionDetectionBuffer:
    def __init__(self, f):
        self.frame_type = 0
        self.soi_seen = False
        self.frame_bytes = io.BytesIO()
        self.callback = f

    def write(self, d):
        if d.startswith(b'\xff\xd8'):
            self.soi_seen = True
            self.frame_bytes.seek(0)
            self.frame_bytes.truncate()
        if self.soi_seen:
            self.frame_bytes.write(d)
            try:
                frame = cv2.imdecode(numpy.frombuffer(self.frame_bytes.getvalue(), numpy.uint8), cv2.IMREAD_COLOR)
                if frame is not None:
                    self.soi_seen = False
                    self.callback(self.frame, frame)
            except Exception as e:
                logger.error("Frame decode error: %s", e)
            self.frame = None
        return len(d)

