import time
import board
import adafruit_dht

# DHT11 sensor on GPIO4 (BCM pin 7)
dht_sensor = adafruit_dht.DHT11(board.D4)

def read_dht11():
    """Read temperature and humidity from the DHT11 sensor."""
    # Attempt to read the sensor up to 5 times
    for attempt_number in range(5):
        try:
            # Read the temperature in Celsius
            temperature_c = dht_sensor.temperature
            if temperature_c is not None:
                # Print the temperature to one decimal place
                print("Temperature: {:.1f} C".format(temperature_c))
                return 0  # Exit cleanly on success
            else:
                print("Attempt {} failed: No reading".format(attempt_number + 1))
        except RuntimeError as error:
            # DHT11 sometimes returns a RuntimeError
            print("Attempt {} failed: {}".format(attempt_number + 1, error))
        except Exception as error:
            # Catch any other unexpected error
            print("Attempt {} failed: {}".format(attempt_number + 1, error))
        time.sleep(2)  # Wait 2 seconds before retrying
    return 1  # Indicate failure after all attempts

if __name__ == "__main__":
    # Run the DHT11 reading and handle the result
    if read_dht11() != 0:
        print("Failed to read DHT11 after multiple attempts.")
    else:
        print("DHT11 reading complete.")

