# rs485 temperature reader for Raspberry Pi using RS485 over USB
# Reads temperature from an RS485 sensor via a USB-to-RS485 adapter
# Uses pyserial to communicate over the serial port

import serial
import time

# Serial port configuration for the USB-to-RS485 adapter
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
SERIAL_TIMEOUT = 1

def open_serial_port(port, baudrate, timeout):
    """Open and configure the serial port."""
    try:
        ser = serial.Serial(port, baudrate, bytesize=8, parity='N', stopbits=1, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_connection):
    """Read a line from the serial port and decode the temperature value."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature = float(line)
                return temperature
            except ValueError:
                print(f"Invalid data received: {line}")
                return None
        return None
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        return None

def main():
    """Main function to continuously read and print temperature data."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, SERIAL_TIMEOUT)

    if serial_connection is None:
        print("Failed to initialize serial communication. Exiting.")
        return

    try:
        while True:
            temperature = read_temperature(serial_connection)
            if temperature is not None:
                print(f"Temperature: {temperature:.1f} C")
            time.sleep(0.5)
    except KeyboardInterrupt:
        print("\nProgram terminated by user.")
    finally:
        if serial_connection and serial_connection.is_open:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

