import time
import logging
import smbus2 as smbus
from functools import partial

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Constants
DHT20_I2C_ADDRESS = 0x38
DHT20_INIT_STATUS_REG = 0x71
DHT20_MEASURE_REG = 0xAC
DHT20_DATA_REG = 0x71
INIT_CHECK_VALUE = 0x18
MEASURE_CMD = [0x33, 0x00]
CRC_POLYNOMIAL = 0x31
DEFAULT_BUS_NUMBER = 1
MAX_RETRIES = 5
RETRY_DELAY = 2  # seconds


class DHT20Error(Exception):
    """Base class for DHT20 exceptions."""
    pass


class DHT20InitializationError(DHT20Error):
    """Raised when DHT20 initialization fails."""
    pass


class DHT20CRCError(DHT20Error):
    """Raised when DHT20 CRC check fails."""
    pass


def _calculate_crc8(data: bytes) -> int:
    """Calculates the CRC8 checksum."""
    crc = 0xFF
    for byte in data:
        crc ^= byte
        for _ in range(8):
            crc = ((crc << 1) ^ CRC_POLYNOMIAL) & 0xFF if crc & 0x80 else (crc << 1) & 0xFF
    return crc


def _read_register(bus: smbus.SMBus, i2c_address: int, register: int, length: int) -> bytes:
    """Reads data from a register."""
    return bus.read_i2c_block_data(i2c_address, register, length)


def _write_register(bus: smbus.SMBus, i2c_address: int, register: int, data: list[int]) -> None:
    """Writes data to a register."""
    bus.write_i2c_block_data(i2c_address, register, data)


def _wait_until_ready(bus: smbus.SMBus, i2c_address: int, register: int, bit: int, timeout: float) -> bool:
    """Waits for a specific bit in the register to be set."""
    start_time = time.time()
    while time.time() - start_time < timeout:
        status = _read_register(bus, i2c_address, register, 1)[0]
        if status & bit:
            return True
        time.sleep(0.001)  # Prevent excessive CPU usage
    return False


def _read_dht20_data(bus: smbus.SMBus, i2c_address: int) -> tuple[int, int]:
    """Reads temperature and humidity data from the DHT20 sensor."""
    if not _wait_until_ready(bus, i2c_address, DHT20_INIT_STATUS_REG, INIT_CHECK_VALUE, 0.1):
        raise DHT20InitializationError("DHT20 not ready within timeout.")

    _write_register(bus, i2c_address, DHT20_MEASURE_REG, MEASURE_CMD)

    if not _wait_until_ready(bus, i2c_address, DHT20_INIT_STATUS_REG, INIT_CHECK_VALUE, 1):
        raise DHT20InitializationError("DHT20 measurement failed.")

    data = _read_register(bus, i2c_address, DHT20_DATA_REG, 7)
    humidity = ((data[1] << 12) | (data[2] << 4) | (data[3] >> 4)) / 1023.0 * 100.0
    temperature = (((data[3] & 0x0F) << 16) | (data[4] << 8) | data[5]) / 4096.0 - 50.0
    crc = _calculate_crc8(data[:-1])

    if crc != data[6]:
        raise DHT20CRCError("DHT20 CRC error.")

    return temperature, humidity


class DHT20:
    """Python driver for the DHT20 temperature and humidity sensor."""

    def __init__(self, i2c_bus_number: int = DEFAULT_BUS_NUMBER, i2c_address: int = DHT20_I2C_ADDRESS) -> None:
        """Initializes the DHT20 driver."""
        self.i2c_bus_number = i2c_address
        self.i2c_address = i2c_address
        self._bus = None

    def __enter__(self):
        """Context manager entry point, opens the I2C bus."""
        self._bus = smbus.SMBus(self.i2c_bus_number)
        return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Context manager exit point, closes the I2C bus."""
        if self._bus:
            self._bus.close()

    def begin(self) -> bool:
        """Initializes the sensor and checks communication."""
        if not self._bus:
            self._bus = smbus.SMBus(self.i2c_address)

        for _ in range(MAX_RETRIES):
            try:
                status = _read_register(self._bus, self.i2c_address, DHT20_INIT_STATUS_REG, 1)[0]
                if (status & INIT_CHECK_VALUE) == INIT_CHECK_VALUE:
                    logger.info("DHT20 initialization successful.")
                    return True
                else:
                    logger.warning(f"DHT20 initialization status: 0x{status:02X}")
            except OSError as e:
                logger.error(f"I2C communication error: {e}")
            time.sleep(RETRY_DELAY)
        logger.error("DHT20 initialization failed after multiple retries.")
        return False

    def get_temperature_and_humidity(self) -> tuple[float | None, float | None, bool]:
        """Retrieves temperature and humidity with error handling."""
        if not self._bus:
            raise DHT20Error("I2C bus not initialized.")

        retry_count = 0
        while retry_count < MAX_RETRIES:
            retry_count += 1
            try:
                temperature, humidity = _read_dht20_data(self._bus, self.i2c_address)
                return temperature, humidity, False
            except (DHT20InitializationError, DHT20CRCError) as e:
                logger.error(f"Sensor error: {e}")
                return None, None, True
            except OSError as e:
                logger.error(f"I2C communication error: {e}")
                return None, None, True
            except Exception as e:
                logger.exception(f"Unexpected error: {e}")
                return None, None, True

        logger.error(f"Failed to read data after {MAX_RETRIES} retries.")
        return None, None, True

    def close(self) -> None:
        """Closes the I2C bus connection."""
        if self._bus:
            self._bus.close()
            self._bus = None


if __name__ == '__main__':
    sensor = DHT20()
    if sensor.begin():
        temperature, humidity, error = sensor.get_temperature_and_humidity()
        if not error:
            print(f"Temperature: {temperature:.2f}°C")
            print(f"Humidity: {humidity:.2f}%")
        else:
            print("Failed to read data.")

