from gpiozero import OutputDevice

# Configure logging
logging.basicConfig(filename='hydroponics.log', level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

def parse_arguments():
    """Parses command-line arguments for configuration."""
    parser = argparse.ArgumentParser(description='Hydroponics Controller')
    parser.add_argument('--relay_pin', type=int, default=17, help='GPIO pin for relay')
    parser.add_argument('--dht_pin', type=int, default=4, help='GPIO pin for DHT11 sensor')
    parser.add_argument('--port', type=int, default=12345, help='TCP port')
    parser.add_argument('--allowed_ip', type=str, default='192.168.1.100', help='Allowed client IP')
    parser.add_argument('--log_file', type=str, default='hydroponics.log', help='Log file path')
    return parser.parse_args()

def setup_gpio(relay_pin):
    """Sets up the GPIO pin for the relay."""
    try:
        relay = OutputDevice(relay_pin, active_high=True, initial_value=False) # Initially OFF
        logging.info(f"Relay pin {relay_pin} set up successfully.")
