import time
import logging
from smbus2 import SMBus
from bmp280 import BMP280

# Configure logging for the Raspberry Pi environmental monitor
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# BMP280 sensor I2C address and bus number
BMP280_ADDRESS = 0x76
I2C_BUS_NUMBER = 1

class CalibrationError(Exception):
    """Custom exception for BMP280 calibration failures."""
    pass

def initialize_bmp280(bus_number, address):
    """Initialize the BMP280 sensor with error handling."""
    try:
        bus = SMBus(bus_number)
        bmp280 = BMP280(i2c_dev=bus, i2c_addr=address)
        # Verify chip ID to confirm sensor presence
        if bus.read_byte_data(address, 0xD0) != 0x58:
            raise CalibrationError("BMP280 chip ID check failed.")
        return bmp280, bus
    except (OSError, CalibrationError) as e:
        logging.error(f"BMP280 initialization failed: {e}")
        raise

def collect_baseline(bmp280, sample_count=100):
    """Collect baseline pressure readings and calculate the trimmed mean."""
    pressures = []
    for _ in range(sample_count):
        try:
            pressures.append(bmp280.get_pressure())
            time.sleep(0.01)
        except OSError as e:
            logging.error(f"Error reading pressure during baseline collection: {e}")
            return None  # Indicate failure
    if not pressures:
        return None
    # Use a 25% trimmed mean to remove outliers
    sorted_pressures = sorted(pressures)
    trimmed_index = int(len(sorted_pressures) * 0.25)
    trimmed_pressures = sorted_pressures[trimmed_index:-trimmed_index]
    if not trimmed_pressures:
        return None
    return sum(trimmed_pressures) / len(trimmed_pressures)

def calculate_altitude(current_pressure, baseline_pressure, sea_level_pressure=1013.25):
    """Calculate relative altitude using the barometric formula."""
    try:
        altitude = 44330 * (1 - (current_pressure / sea_level_pressure)**(1/5.255))
        return altitude
    except (TypeError, ZeroDivisionError) as e:
        logging.error(f"Error calculating altitude: {e}")
        return None

def main():
    """Main function to run the environmental monitoring loop."""
    try:
        bmp280, bus = initialize_bmp280(I2C_BUS_NUMBER, BMP280_ADDRESS)
        baseline_pressure = collect_baseline(bmp280)

        if baseline_pressure is None:
            logging.warning("Failed to establish baseline pressure. Using default sea level pressure.")
            baseline_pressure = 1013.25  # Default sea level pressure in hPa

        while True:
            try:
                current_pressure = bmp280.get_pressure()
                altitude = calculate_altitude(current_pressure, baseline_pressure)
                if altitude is not None:
                    logging.info(f"Relative altitude: {altitude:.2f} meters")
                time.sleep(1)
            except OSError as e:
                logging.error(f"Sensor read error: {e}")
                time.sleep(1)
    except KeyboardInterrupt:
        logging.info("Program terminated by user.")
    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        # Ensure the I2C bus is closed on exit
        try:
            bus.close()
        except AttributeError:
            pass # bus might not have a close method if initialization failed
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

