# Reads temperature from a serial device and logs it to a CSV file.
import serial
import time
import csv
import os

# Serial port configuration
SERIAL_PORT = '/dev/ttyACM0'
BAUD_RATE = 115200
TIMEOUT = 1

# CSV file path
LOG_FILE = 'temperature_log.csv'

def open_serial_port(port, baudrate, timeout):
    """Opens the serial port and returns a serial object."""
    try:
        ser = serial.Serial(port, baudrate, timeout=timeout)
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def read_temperature(serial_port):
    """Reads a line from the serial port and returns the temperature in Celsius."""
    try:
        line = serial_port.readline().decode('ascii', errors='replace').strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print(f"Invalid data received: {line}")
        return None

def convert_to_fahrenheit(celsius):
    """Converts Celsius to Fahrenheit."""
    return celsius * 9/5 + 32

def log_temperature(log_file, timestamp, celsius, fahrenheit):
    """Logs the temperature data to the CSV file."""
    try:
        with open(log_file, 'a', newline='') as csvfile:
            writer = csv.writer(csvfile)
            writer.writerow([timestamp, celsius, fahrenheit])
    except IOError as e:
        print(f"Error writing to log file: {e}")

def main():
    """Main function to read temperature and log it to a CSV file."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)

    if serial_connection is None:
        print("Failed to open serial port. Exiting.")
        return

    try:
        while True:
            temperature_celsius = read_temperature(serial_connection)
            if temperature_celsius is not None:
                temperature_fahrenheit = convert_to_fahrenheit(temperature_celsius)
                current_time = time.strftime("%Y-%m-%d %H:%M:%S")
                log_temperature(LOG_FILE, current_time, temperature_celsius, temperature_fahrenheit)
                print(f"Logged: {current_time}, {temperature_celsius:.2f}C, {temperature_fahrenheit:.2f}F")
            time.sleep(1)  # Reduced sleep time for responsiveness
    except KeyboardInterrupt:
        print("Exiting program.")
    finally:
        serial_connection.close()
        print("Serial port closed.")

if __name__ == "__main__":
    main()

