# Script to read temperature and humidity from a serial sensor on Raspberry Pi
# and trigger alerts when thresholds are exceeded.

import serial
import time

# Serial port configuration for the sensor
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 9600
TIMEOUT = 1

# Thresholds for temperature and humidity
TEMPERATURE_THRESHOLD = 30.0
HUMIDITY_THRESHOLD = 70.0

def read_sensor_data(serial_connection):
    """Reads a line from the serial port and returns it as a string."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        return line
    except serial.SerialException as e:
        print(f"Serial read error: {e}")
        return None

def parse_sensor_data(data_string):
    """Parses the comma-separated data string into temperature and humidity values."""
    try:
        temperature, humidity = data_string.split(',')
        temperature = float(temperature)
        humidity = float(humidity)
        return temperature, humidity
    except ValueError:
        print("Invalid data format received.")
        return None, None

def check_thresholds(temperature, humidity):
    """Checks if temperature or humidity exceeds the defined thresholds."""
    if temperature is not None and humidity is not None:
        if temperature > TEMPERATURE_THRESHOLD:
            print('ALERT: High temperature detected!')
        if humidity > HUMIDITY_THRESHOLD:
            print('ALERT: High humidity detected!')

def main():
    """Main function to read sensor data and check thresholds."""
    serial_connection = None
    try:
        # Open the serial port
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        print(f"Connected to serial port {SERIAL_PORT}")

        # Continuously read and process data
        while True:
            data = read_sensor_data(serial_connection)
            if data:
                temperature, humidity = parse_sensor_data(data)
                if temperature is not None and humidity is not None:
                    print(f"Temperature: {temperature:.1f}°C, Humidity: {humidity:.1f}%")
                    check_thresholds(temperature, humidity)
            time.sleep(1)

    except serial.SerialException as e:
        print(f"Could not open serial port {SERIAL_PORT}: {e}")
    except KeyboardInterrupt:
        print("Program interrupted by user.")
    finally:
        # Ensure the serial port is closed on exit
        if serial_connection:
            serial_connection.close()
            print("Serial port closed.")

if __name__ == "__main__":
    main()

