import RPi.GPIO as GPIO
import time
import requests

# Define the GPIO pin connected to the voltage sensor
VOLTAGE_SENSOR_PIN = 17

# Define the URL to send alerts to
ALERT_ENDPOINT = "http://example.com/alert"

# Configure GPIO settings
GPIO.setmode(GPIO.BCM)
GPIO.setup(VOLTAGE_SENSOR_PIN, GPIO.IN, pull_up_down=GPIO.PUD_UP)


def check_voltage_status():
    """Read the voltage sensor and return True if power is present, False otherwise."""
    return GPIO.input(VOLTAGE_SENSOR_PIN) == GPIO.HIGH


def send_power_failure_alert():
    """Send an HTTP POST request to the alert endpoint."""
    try:
        requests.post(ALERT_ENDPOINT, json={"alert": "Power failure detected"}, timeout=5)
    except requests.exceptions.RequestException as request_error:
        print(f"Alert request failed: {request_error}")


def main():
    """Main function to monitor voltage and send alerts."""
    try:
        while True:
            if check_voltage_status():
                print("Power present")
            else:
                print("Power failure detected")
                send_power_failure_alert()
            time.sleep(1)
    except KeyboardInterrupt:
        print("Monitoring stopped by user")
    finally:
        GPIO.cleanup()


if __name__ == "__main__":
    main()

