import zmq
import time
import json
import RPi.GPIO as GPIO
import gpiozero
import requests
import logging
import signal
import sys
from typing import Callable, Any, Dict, List, Tuple

class SubscriptionHandler:
    """
    Manages subscriptions to data streams and executes callbacks.
    """

    def __init__(self):
        self.subscriptions: Dict[str, List[Tuple[int, Callable]]] = {}
        self.subscriber_socket: zmq.Socket = None
        self.logger: logging.Logger = logging.getLogger(__name__)

    def connect(self, subscriber_socket: zmq.Socket):
        """Connects the handler to a subscriber socket."""
        self.subscriber_socket = subscriber_socket

    def handle_message(self, message: str) -> None:
        """Handles incoming subscription messages."""
        try:
            data = json.loads(message)
            stream_id = data.get('stream_id')
            callback = data.get('callback')

            if not all([stream_id, callback]):
                self.logger.warning("Invalid subscription message format.")
                return

            if stream_id not in self.subscriptions:
                self.subscriptions[stream_id] = []

            for sub_id, _ in self.subscriptions[stream_id]:
                if self.subscriber_socket.getsockopt(zmq.SUBSCRIBE) == stream_id:
                    self.subscriptions[stream_id].append((sub_id, callback))
                    self.logger.info(f"Callback '{callback.__name__}' subscribed to '{stream_id}'.")
                    return

            self.subscriber_socket.setsockopt_string(zmq.SUBSCRIBE, stream_id)
            self.subscriptions[stream_id].append((sub_id, callback))
            self.logger.info(f"Callback '{callback.__name__}' subscribed to '{stream_id}'.")
        except json.JSONDecodeError as e:
            self.logger.error(f"Error decoding JSON: {e}")
        except Exception as e:
            self.logger.exception(f"Error handling message: {e}")

    def run_callbacks(self, stream_id: str, message: dict) -> None:
        """Runs all subscribed callbacks for a given stream."""
        if stream_id in self.subscriptions:
            for sub_id, callback in self.subscriptions[stream_id]:
                try:
                    callback(message, stream_id, sub_id)
                except Exception as e:
                    self.logger.exception(f"Error executing callback for '{stream_id}': {e}")



class PIDHandler:
    """
    Manages PID controllers and error outputs.
    """

    def __init__(self, logger: logging.Logger, config: dict):
        self.pid_lock: dict = {}
        self.global_err_state: bool = False
        self.last_msg: float = time.time()
        self.sub_handler: SubscriptionHandler = SubscriptionHandler()
        self.logger = logger
        self.config = config
        self.error_output: Any = None  # Initialize as None
        self.is_running = True  # Flag to control the main loop

        # Configure signal handler for clean exit
        signal.signal(signal.SIGINT, self.cleanup)
        signal.signal(signal.SIGTERM, self.cleanup)


    def initialize_gpio(self):
        """Initializes GPIO pins for PWM or digital output."""
        try:
            if self.config.get('pwm'):
                self.error_output = gpiozero.PWMOutputDevice(12, True, 1000, 0.0)  # PWM on GPIO 12
                self.logger.info("Initialized PWM output on GPIO 12.")
            else:
                self.error_output = gpiozero.OutputDevice(10, True)  # Digital output on GPIO 10
                self.logger.info("Initialized digital output on GPIO 10.")
        except gpiozero.exc.GPIODeviceError as e:
            self.logger.error(f"Failed to initialize GPIO: {e}")
            self.is_running = False  # Stop the application if GPIO initialization fails
            return False
        except Exception as e:
            self.logger.exception(f"Unexpected error during GPIO initialization: {e}")
            self.is_running = False
            return False
        return True


    def handle_subscription(self, subscriber_socket: zmq.Socket):
        """Handles subscription messages."""
        self.sub_handler.connect(subscriber_socket)
        subscriber_socket.setsockopt(zmq.SUBSCRIBE, b"")  # Subscribe to all streams initially

        while self.is_running:
            try:
                message = subscriber_socket.recv_string(flags=zmq.NOBLOCK)  # Non-blocking receive
                self.last_msg = time.time()
                self.sub_handler.handle_message(message)
            except zmq.ZMQError as e:
                if e.errno == zmq.EAGAIN:
                    if time.time() - self.last_msg > 20:  # Watchdog timeout
                        self.logger.error("Watchdog timeout: No message received for 20 seconds. Exiting.")
                        self.is_running = False
                    continue
                else:
                    self.logger.error(f"ZMQError: {e}")
                    break  # Exit on other ZMQ errors
            except Exception as e:
                self.logger.exception(f"Error handling subscription: {e}")
                break

    def update_error_output(self, stream_id: str, control: dict) -> None:
        """Updates the error output based on stream status."""
        key = (stream_id, control)
        if key not in self.pid_lock:
            self.pid_lock[key] = False

        if control.get('action') == 'new':
            self.pid_lock[key] = True
            status = control.get('status', {})
            self.global_err_state = status.get('ERROR', False)
            self.apply_pid_control(stream_id, status)
            self.pid_lock[key] = False

        elif control.get('action') == 'remove':
            # No direct action needed, lock prevents updates while removal is processed.
            pass

        if self.global_err_state:
            if self.config.get('pwm'):
                self.error_output.value = 1.0
            else:
                self.error_output.on()
            self.logger.warning(f"Global error state: {self.global_err_state} for stream: {stream_id}")
        else:
            if self.config.get('pwm'):
                self.error_output.value = 0.0
            else:
                self.error_output.off()

    def apply_pid_control(self, stream_id: str, status: dict) -> None:
        """Applies PID control based on stream status."""
        key = (stream_id, status)
        if self.pid_lock.get(key):
            return

        if status.get('ERROR'):
            self.logger.error(f"PID Control ERROR for {stream_id}")
            # Implement your PID error handling logic here
        else:
            # Implement your PID control logic here
            self.logger.info(f"PID Control OK for {stream_id}")

    def cleanup(self, signum, frame):
        """Cleans up GPIO and exits."""
        self.logger.info("Cleaning up and exiting...")
        if self.error_output:
            try:
                if self.config.get('pwm'):
                    self.error_output.close()
                else:
                    self.error_output.off()
                    self.error_output.close()
            except Exception as e:
                self.logger.error(f"Error cleaning up GPIO: {e}")
        sys.exit(0)

