# -*- coding: utf-8 -*-
"""
Reads ambient luminance from a BH1750FVI light sensor over I2C on a Raspberry Pi.
"""

import time
import smbus2
import signal
import sys

# BH1750FVI I2C address and register definitions
BH1750_I2CADDR = 0x23
BH1750_CONTINUOUS_HIGH_RES_MODE = 0x10

# Global variable to hold the I2C bus
i2c_bus = None

def initialize_sensor():
    """Initializes the BH1750FVI light sensor."""
    global i2c_bus
    try:
        i2c_bus = smbus2.SMBus(1)  # Use I2C bus 1
        i2c_bus.write_byte(BH1750_I2CADDR, 0x01)  # Power on
        i2c_bus.write_byte(BH1750_I2CADDR, BH1750_CONTINUOUS_HIGH_RES_MODE)  # Set to high resolution mode
        print("BH1750 sensor initialized successfully.")
    except Exception as e:
        print(f"Error initializing BH1750: {e}")
        sys.exit(1)

def read_luminance():
    """Reads the ambient luminance in lux from the BH1750 sensor."""
    try:
        data = i2c_bus.read_i2c_block_data(BH1750_I2CADDR, BH1750_CONTINUOUS_HIGH_RES_MODE, 2)
        luminance = (data[0] << 8 | data[1]) / 1.2
        return luminance
    except Exception as e:
        print(f"Error reading luminance: {e}")
        return None

def signal_handler(sig, frame):
    """Handles Ctrl+C to exit gracefully."""
    print("\nExiting program...")
    if i2c_bus:
        try:
            i2c_bus.close()
            print("I2C bus closed.")
        except Exception as e:
            print(f"Error closing I2C bus: {e}")
    sys.exit(0)

def main():
    """Main function to read and print luminance."""
    initialize_sensor()
    signal.signal(signal.SIGINT, signal_handler)

    try:
        while True:
            luminance = read_luminance()
            if luminance is not None:
                print(f"Ambient Luminance: {luminance:.2f} lux")
            time.sleep(1)
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if i2c_bus:
            try:
                i2c_bus.close()
                print("I2C bus closed.")
            except Exception as e:
                print(f"Error closing I2C bus: {e}")

if __name__ == "__main__":
    main()

