# Rotary encoder for Raspberry Pi using gpiozero with debounce
# Connect CLK to GPIO17, DT to GPIO18, both with pull-up resistors
# Debounce time is set to 5 ms to filter mechanical noise
import time
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from functools import partial

class RotaryEncoder:
    """A class to handle a KY-040 rotary encoder on a Raspberry Pi."""

    def __init__(self, clk_pin, dt_pin, callback=None, initial_value=0):
        """Initialize the rotary encoder.

        Args:
            clk_pin (int): BCM GPIO pin for the CLK signal.
            dt_pin (int): BCM GPIO pin for the DT signal.
            callback (callable, optional): Function to call on rotation. 
                                            Defaults to None.
            initial_value (int, optional): Initial value of the counter. 
                                           Defaults to 0.
        """
        self.clk_pin = clk_pin
        self.dt_pin = dt_pin
        self.callback = callback
        self.initial_value = initial_value
        self.value = self.initial_value
        self.last_clk_state = None
        self.debounce_time = 0.005  # 5ms debounce time

        # Initialize GPIO input devices with pull-up resistors
        try:
            self.clk = DigitalInputDevice(self.clk_pin, pull_up=True)
            self.dt = DigitalInputDevice(self.dt_pin, pull_up=True)
        except Exception as e:
            raise RuntimeError(f"Error initializing GPIO pins: {e}")

        # Use partial to create a callback function that passes the encoder instance
        if self.callback:
            if not callable(self.callback):
                raise TypeError("Callback must be callable.")
            self._rotation_callback = partial(self._rotation_callback, encoder=self)
            self.clk.when_changed = self._rotation_callback
        else:
            self.clk.when_changed = self._no_callback

    def _no_callback(self, *args, **kwargs):
        """No-op callback function."""
        pass

    def _rotation_callback(self, *args, **kwargs):
        """Internal callback function for rotary encoder rotation."""
        clk_state = self.clk.value
        if clk_state != self.last_clk_state:
            dt_state = self.dt.value
            if dt_state != clk_state:
                self.value += 1
            else:
                self.value -= 1
            self.last_clk_state = clk_state
            self._update_callback()

    def _update_callback(self):
        """Update the callback function based on the current value."""
        if self.callback:
            try:
                self.callback(self.value)  # Execute the callback safely
            except Exception as e:
                print(f"Error in callback function: {e}")

    def get_value(self):
        """Return the current value of the encoder."""
        return self.value

    def cleanup(self):
        """Clean up the GPIO pins."""
        try:
            self.clk.close()
            self.dt.close()
        except Exception as e:
            print(f"Error cleaning up GPIO pins: {e}")


if __name__ == "__main__":
    def my_callback(value):
        """Example callback function."""
        print(f"Encoder value: {value}")

    try:
        encoder = RotaryEncoder(clk_pin=17, dt_pin=18, callback=my_callback, initial_value=50)
        print("Rotary encoder example. Press Ctrl+C to exit.")
        while True:
            time.sleep(0.1)  # Reduce CPU usage
    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An error occurred: {e}")
    finally:
        if 'encoder' in locals():
            encoder.cleanup()

