DEFAULT_DIM_WHITE = (1, 1, 1)  # Dim white color for the APA102 strip
MIDDLE_C = 60

# Global variables
bit_states = [False, False, False]  # Initial state of the 3 bits
strip = None  # APA102 LED strip object
buzzer = None # Buzzer object

# Initialize GPIO if available
if GPIO:
    GPIO.setmode(GPIO.BCM)

# --- Helper Functions ---
def calculate_decimal_value(bit_states):
    """Calculates the decimal value of the 3-bit binary string represented by bit_states."""
    return sum(2**i * bit_states[i] for i in range(3))

def display_decimal_value(value):
    """Displays the decimal value on the 14-segment display."""
    if display:
        try:
            display.print_hex(value)
            display.show()
        except Exception as e:
            logging.error(f"Error displaying value on display: {e}")

def update_leds(value):
    """Updates the discrete RGB LEDs based on the decimal value."""
    if leds:
        try:
            if value == 0:
                leds.all_off()
            else:
                red, green, blue = (0, 0, 0) if bit_states[0] else (255, 0, 0)  # Red if bit 0 is True
                if bit_states[1]:
                    red, green, blue = (0, 255, 0)  # Green if bit 1 is True
                if bit_states[2]:
                    red, green, blue = (0, 0, 255)  # Blue if bit 2 is True
                leds.rgb(red, green, blue)
        except Exception as e:
            logging.error(f"Error controlling LEDs: {e}")

def update_strip(value):
    """Updates the APA102 LED strip based on the decimal value."""
    global strip
    if strip is None:
        return  # LED strip not initialized

    try:
        if value == 0:
            strip.clear()
            strip.set_pixel(0, *DEFAULT_DIM_WHITE)  # Dim white at index 0
            strip.show()
        elif value == 7:
            for i in range(strip.num_pixels()):
                strip.set_pixel(i, 255, 255, 255)
            strip.show()
        else:
            strip.set_pixel(value, *DEFAULT_DIM_WHITE)
            strip.show()
    except Exception as e:
        logging.error(f"Error controlling LED strip: {e}")

def play_tone(value):
    """Plays a tone on the piezo buzzer based on the decimal value."""
    if buzzer is None:
        return # Buzzer not initialized

    try:
        buzzer.on()
        buzzer.frequency = MIDDLE_C + value
        time.sleep(TONE_DURATION)
        buzzer.off()
    except Exception as e:
        logging.error(f"Error playing tone: {e}")

def handle_touch(channel):
    """Handles touchpad press events and updates the binary counter."""
    global bit_states

    try:
        if channel == 0:  # Touchpad A (most significant bit)
            bit_states[0] = not bit_states[0]
        elif channel == 2:  # Touchpad B
            bit_states[1] = not bit_states[1]
        elif channel == 3:  # Touchpad C (least significant bit)
            bit_states[2] = not bit_states[2]
    except Exception as e:
        logging.error(f"Error handling touch event: {e}")
        return

    value = calculate_decimal_value(bit_states)
    display_decimal_value(value)
    update_leds(value)
    update_strip(value)
    play_tone(value)

def initialize_hardware():
    """Initializes the hardware components (display, LEDs, strip, buzzer)."""
    global strip, buzzer

    if display:
        try:
            display.clear()
            display.show()
        except Exception as e:
            logging.error(f"Error initializing display: {e}")

    if leds:
        try:
            leds.all_off()
        except Exception as e:
            logging.error(f"Error initializing LEDs: {e}")

    if strip:
        try:
            strip.begin()
            strip.clear()
            strip.show()
        except Exception as e:
            logging.error(f"Error initializing LED strip: {e}")
            strip = None # Disable the strip if initialization fails

    if buzzer:
        try:
            buzzer.on()
            time.sleep(0.1)
            buzzer.off()
        except Exception as e:
            logging.error(f"Error initializing buzzer: {e}")
            buzzer = None # Disable the buzzer if initialization fails

def cleanup_hardware():
    """Releases the hardware resources."""
    logging.info("Cleaning up hardware...")

    if display:
        try:
            display.clear()
            display.show()
        except Exception as e:
            logging.error(f"Error clearing display during cleanup: {e}")

    if leds:
        try:
            leds.all_off()
        except Exception as e:
            logging.error(f"Error turning off LEDs during cleanup: {e}")

    if strip:
        try:
            strip.clear()
            strip.show()
        except Exception as e:
            logging.error(f"Error clearing LED strip during cleanup: {e}")

    if buzzer:
        try:
            buzzer.off()
        except Exception as e:
            logging.error(f"Error turning off buzzer during cleanup: {e}")

    if GPIO:
        try:
            GPIO.cleanup()
        except Exception as e:
            logging.error(f"Error cleaning up GPIO during cleanup: {e}")

def signal_handler(signum, frame):
    """Handles signals for graceful shutdown."""
    logging.info(f"Received signal {signum}. Shutting down...")
    cleanup_hardware()
    sys.exit(0)

# --- Main Program ---
if __name__ == "__main__":

    # Register signal handlers
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    # Initialize hardware
    initialize_hardware()

    # Setup touchpad event handling if evdev is available
    if evdev:
        try:
            for touchpad in evdev.list_devices():
                if touchpad.name == 'Rainbow HAT Touchpad':
                    device = evdev.InputDevice(touchpad.device)
                    for event in device.read_loop():
                        if event.type == evdev.ecodes.EV_KEY and event.value == 1:  # Key down
                            channel = event.code
                            handle_touch(channel)
                            break # Only handle one touch per event
        except Exception as e:
            logging.error(f"Error initializing touchpad: {e}")
    elif GPIO: # Fallback to GPIO if evdev is unavailable
        try:
            GPIO.setup(5, GPIO.IN, pull_up_down=GPIO.PUD_UP)  # Touchpad A
            GPIO.setup(6, GPIO.IN, pull_up_down=GPIO.PUD_UP)  # Touchpad B
            GPIO.setup(12, GPIO.IN, pull_up_down=GPIO.PUD_UP) # Touchpad C

            GPIO.add_event_detect(5, GPIO.FALLING, callback=handle_touch, bouncetime=200)
            GPIO.add_event_detect(6, GPIO.FALLING, callback=handle_touch, bouncetime=200)
            GPIO.add_event_detect(12, GPIO.FALLING, callback=handle_touch, bouncetime=200)

            logging.info("Touchpad event handling initialized (GPIO fallback).")
        except Exception as e:
            logging.error(f"Error setting up touchpad events (GPIO): {e}")
    else:
        logging.warning("No touchpad support available.")

    # Keep the program running
    logging.info("Press Ctrl+C to exit.")
    if pause:
        pause()  # Wait for touch events
    else:
        while True:
            time.sleep(0.1)  # Check for exit signal occasionally

    # Cleanup on exit
    atexit.register(cleanup_hardware)

