import time
import signal
import sys
import board
import busio
import adafruit_tcs34725
from PIL import Image

# Constants
IMAGE_FILE = 'image.jpg'
RESIZE_WIDTH = 100
RESIZE_HEIGHT = 100
DEFAULT_INTEGRATION_TIME = 0x00  # 50ms
DEFAULT_GAIN = 0x00  # 4x

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_sensor(i2c_bus):
    """Initializes the TCS34725 color sensor."""
    try:
        return adafruit_tcs34725.TCS34725(i2c_bus, address=0x29, integration_time=DEFAULT_INTEGRATION_TIME, gain=DEFAULT_GAIN)
    except Exception as e:
        print(f"Error initializing sensor: {e}")
        return None

def get_sensor_color_data(sensor):
    """Reads color data from the sensor."""
    try:
        r, g, b, c = sensor.color_rgb_bytes
        return r, g, b, c
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return 0, 0, 0, 0

def find_dominant_image_color(image_path):
    """Finds the dominant color in an image."""
    try:
        img = Image.open(image_path)
        resized_img = img.resize((RESIZE_WIDTH, RESIZE_HEIGHT))
        colors = resized_img.getcolors(10000)
        if colors:
            dominant_color = max(colors, key=lambda item: item[0])[1]
            return dominant_color
        else:
            return (0, 0, 0)  # Return black if no colors are found
    except FileNotFoundError:
        print(f"Error: Image file '{image_path}' not found.")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main_loop(sensor):
    """Main loop to read sensor data and process image."""
    try:
        while True:
            r, g, b, c = get_sensor_color_data(sensor)
            dominant_color = find_dominant_image_color(IMAGE_FILE)
            print(f"Sensor: R={r}, G={g}, B={b}, Clear={c}, Image Dominant Color: {dominant_color}")
            time.sleep(1)
    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")

def signal_handler(sig, frame):
    """Handles signals for clean shutdown."""
    print("Received signal, shutting down...")
    sys.exit(0)

if __name__ == "__main__":
    i2c_bus = initialize_i2c()
    if i2c_bus:
        sensor = initialize_sensor(i2c_bus)
        if sensor:
            signal.signal(signal.SIGINT, signal_handler)
            main_loop(sensor)
        else:
            i2c_bus.deinit()
    else:
        print("Failed to initialize I2C, exiting.")

