import socket
import json
import time
import logging
import signal
import sys
import random
try:
    import serial
    gps_available = True
except ImportError:
    gps_available = False
try:
    import smbus2
    gps_available = True
except ImportError:
    gps_available = False

# Configure logging for the wildlife-tracking remote control server
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")
server_logger = logging.getLogger("wildlife_server")

# Network configuration for the IoT remote control socket
LISTEN_ADDRESS = "127.0.0.1"
LISTEN_PORT = 9099
MAX_CONNECTIONS = 5


def read_gps_position(gps_device):
    """Read a latitude and longitude from the GPS device, or simulate one."""
    # Read a real GPS module over serial or I2C, or fall back to simulation
    if gps_available and gps_device:
        try:
            if gps_device.port == "uart":
                # Read a raw NMEA line from the UART GPS module
                raw_line = gps_device.readline().decode("utf-8", errors="ignore")
                if raw_line.startswith("$GPGGA"):
                    parts = raw_line.split(",")
                    if len(parts) >= 7 and parts[6] == "1":
                        return float(parts[2]), float(parts[4])
            else:
                # Read a raw I2C register block from the GPS module
                try:
                    # Read the first 20 bytes of the GPS register block
                    gps_data = gps_device.read_i2c_block_data(0x42, 0, 20)
                    return float(gps_data[0]), float(gps_data[1])
                except Exception:
                    pass
        except Exception:
            pass
    # Return a simulated coordinate if the GPS module is absent or fails
    return round(random.uniform(-90.0, 90.0), 6), round(random.uniform(-180.0, 180.0), 6)


def handle_command(command_text, gps_device):
    """Process a remote control command and return a JSON reply."""
    # Parse the command text into a dictionary of arguments
    command = json.loads(command_text)
    reply_payload = {"status": "ok", "lat": None, "lon": None}
    try:
        if command["action"] == "start":
            # Mark the tracking session as running on the Raspberry Pi
            server_logger.info("Tracking session started")
        elif command["action"] == "stop":
            # Mark the tracking session as stopped on the Raspberry Pi
            server_logger.info("Tracking session stopped")
        elif command["action"] == "report":
            # Read the current GPS position and include it in the reply
            lat, lon = read_gps_position(gps_device)
            reply_payload["lat"] = lat
            reply_payload["lon"] = lon
        else:
            # Reject any unknown remote control command
            reply_payload["status"] = "unknown"
        return json.dumps(reply_payload)
    except (KeyError, ValueError) as parse_error:
        # Log any parsing or validation failure of the command
        server_logger.error("Invalid command: %s", command_text)
        return json.dumps({"status": "error", "reason": str(parse_error)})


def main():
    """Listen for remote control commands and reply with GPS coordinates."""
    # Open a TCP socket bound to the server address and port
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
    server_socket.settimeout(2.0)
    try:
        server_socket.bind((LISTEN_ADDRESS, LISTEN_PORT))
        server_socket.listen(MAX_CONNECTIONS)
        server_logger.info("Listening on %s:%d", LISTEN_ADDRESS, LISTEN_PORT)
        # Accept a single connection and process one remote control command
        connection, address = server_socket.accept()
        with connection:
            command_text = connection.recv(1024).decode("utf-8", errors="ignore")
            reply_text = handle_command(command_text, None)
            connection.sendall(reply_text.encode("utf-8"))
    except socket.timeout:
        server_logger.warning("No connection accepted within timeout")
    except Exception as server_error:
        # Log any socket or GPS failure during remote control
        server_logger.error("Server error: %s", server_error)
    finally:
        # Close the listening socket and any open GPS device
        server_socket.close()


if __name__ == "__main__":
    # Run the wildlife-tracking remote control server
    main()

