#!/usr/bin/python3
# -*- coding: utf-8 -*-
"""
Provides a low-level driver for a DC motor controlled via an L298N driver
using the pigpio library.  Includes safety guards and resource management.
"""

import pigpio
from functools import partial
from typing import Optional, Callable

# Constants
DEFAULT_FREQUENCY = 1000  # Hz
DEFAULT_DUTY_CYCLE = 0    # 0% duty cycle
MAX_PWM_VALUE = 255
MOTOR_FORWARD = 1
MOTOR_BACKWARD = 0

# Error handling
class MotorError(Exception):
    """Custom exception for motor-related errors."""
    pass


def _validate_pin(pin: int) -> None:
    """Validate the GPIO pin."""
    if not isinstance(pin, int):
        raise TypeError("Pin must be an integer.")


def _set_gpio_mode(pi: pigpio.pi, pin: int, mode: int) -> None:
    """Set the mode of a GPIO pin."""
    _validate_pin(pin)
    try:
        pi.set_mode(pin, mode)
    except pigpio.error as e:
        raise MotorError(f"Failed to set pin {pin} mode: {e}") from e


def _pwm_core(pi: pigpio.pi, pin: int, frequency: int, duty_cycle: int) -> None:
    """Core PWM control logic, separated for easier testing and reuse."""
    _validate_pin(pin)
    if not 0 <= duty_cycle <= MAX_PWM_VALUE:
        raise ValueError(f"Duty cycle must be between 0 and {MAX_PWM_VALUE}: {duty_cycle}")

    try:
        pi.set_PWM_frequency(pin, frequency)
        pi.set_PWM_dutycycle(pin, duty_cycle)
    except pigpio.error as e:
        raise MotorError(f"Failed to set PWM on pin {pin}: {e}") from e


def _create_motor(pi: pigpio.pi, pin: int, inverted: bool = False) -> "Motor":
    """Factory function to create a Motor instance."""
    _validate_pin(pin)
    if not isinstance(pi, pigpio.pi):
        raise TypeError("pi must be a pigpio.pi instance.")

    _set_gpio_mode(pi, pin, pigpio.OUTPUT)
    frequency = DEFAULT_FREQUENCY
    duty_cycle = DEFAULT_DUTY_CYCLE

    _pwm_core(pi, pin, frequency, duty_cycle)

    return Motor(pi, pin, inverted, frequency)


class Motor:
    """Represents a DC motor controlled via an L298N driver."""

    def __init__(self, pi: pigpio.pi, pin: int, inverted: bool = False, frequency: int = DEFAULT_FREQUENCY):
        """Initialize a Motor instance."""
        self.pi = pi
        self.pin = pin
        self.inverted = bool(inverted)  # Ensure boolean type
        self.frequency = frequency
        self._duty_cycle = DEFAULT_DUTY_CYCLE

        self._set_duty_cycle = partial(self._set_safe_duty_cycle, invert=self.inverted)

    def _set_safe_duty_cycle(self, duty_cycle: int, invert: bool) -> None:
        """Safe wrapper for _pwm_core, handling inversion."""
        try:
            if invert:
                duty_cycle = -duty_cycle
            _pwm_core(self.pi, self.pin, self.frequency, duty_cycle)
        except MotorError as e:
            print(f"Error setting motor duty cycle: {e}")

    def set_frequency(self, frequency: int) -> None:
        """Set the PWM frequency for the motor."""
        if not isinstance(frequency, int):
            raise TypeError("Frequency must be an integer.")
        self.frequency = frequency
        self._set_duty_cycle(self._duty_cycle, self.inverted)  # Update frequency


    def set_duty_cycle(self, duty_cycle: int) -> None:
        """Set the duty cycle of the motor."""
        if not isinstance(duty_cycle, int):
            raise TypeError("Duty cycle must be an integer.")
        self._duty_cycle = duty_cycle
        self._set_duty_cycle(self._duty_cycle, self.inverted)  # Update duty cycle


    def set_speed(self, speed: float) -> None:
        """Set the motor speed as a percentage (-1.0 to 1.0)."""
        if not -1.0 <= speed <= 1.0:
            raise ValueError("Speed must be between -1.0 and 1.0.")
        duty_cycle = int(speed * DEFAULT_DUTY_CYCLE)
        self.set_duty_cycle(duty_cycle)


    def stop(self) -> None:
        """Stop the motor."""
        self.set_duty_cycle(DEFAULT_DUTY_CYCLE)

    def close(self) -> None:
        """Stop the motor and release resources."""
        self.stop()
        _set_gpio_mode(self.pi, self.pin, pigpio.INPUT)  # Leave pin in INPUT mode

    def __repr__(self) -> str:
        """Return a string representation of the motor's state."""
        return (f"Motor(pin={self.pin}, inverted={self.inverted}, "
                f"frequency={self.frequency}, duty_cycle={self._duty_cycle})")



def create_and_start_motor(pi: pigpio.pi, pin: int, mode: str = "forward") -> Motor:
    """Create a Motor instance and start it in the specified mode."""
    if mode == "forward":
        return _create_motor(pi, pin, MOTOR_FORWARD)
    elif mode == "backward":
        return _create_motor(pi, pin, MOTOR_BACKWARD)
    else:
        raise ValueError("Invalid mode. Use 'forward' or 'backward'.")


if __name__ == "__main__":
    # Example usage (requires Raspberry Pi and pigpio):
    pi = pigpio.pi()
    if not pi.connected:
        raise RuntimeError("Failed to connect to pigpio daemon.")

    try:
        motor = create_and_start_motor(pi, 18, mode="forward")
        print(f"Motor started in forward mode: {motor}")
        motor.set_speed(0.5)  # Set speed to 50%
        motor.set_frequency(1200) # Set frequency to 1200 Hz
        print(f"Motor frequency set to: {motor.frequency}")

    except MotorError as e:
        print(f"Motor error: {e}")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        if motor:
            motor.close()  # Ensure motor is stopped and resources released.
        pi.stop()

