#!/usr/bin/env python3
"""Module for managing a garage door using a Raspberry Pi and Pimoroni Automation HAT."""

import time
import logging
import sys
import signal

try:
    import automationhat
except ImportError:
    print("Error: automationhat library not found. Please install it.")
    sys.exit(1)

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Define constants
RELAY_PIN = 1
TRIGGER_DURATION = 0.5  # seconds
GARAGE_DOOR_CLOSED = 1
GARAGE_DOOR_OPEN = 0


class GarageDoor:
    """
    A class to represent and control a garage door using a Pimoroni Automation HAT relay.
    """

    def __init__(self, state_pin=0, trigger_duration=TRIGGER_DURATION):
        """
        Initializes the GarageDoor object.

        Args:
            state_pin (int): The state pin number on the Automation HAT.
            trigger_duration (float): The duration the relay is activated to trigger the door.
        """
        if not isinstance(state_pin, int):
            raise TypeError("state_pin must be an integer.")
        if not 0 <= state_pin <= 3:
            raise ValueError("state_pin must be between 0 and 3 (inclusive).")

        self.state_pin = state_pin
        self.trigger_duration = trigger_duration
        logger.info("Garage door initialized.")


    def trigger(self):
        """
        Activates the relay momentarily to simulate pressing the garage door opener button.
        """
        try:
            automationhat.relay.on()
            time.sleep(self.trigger_duration)
            automationhat.relay.off()
            logger.info("Garage door triggered.")
        except Exception as e:
            logger.error(f"Error triggering garage door: {e}")
            raise


    @property
    def state(self):
        """
        Returns:
            int: 1 if the door is closed, 0 if the door is open. Raises an exception if there's an error.
        """
        try:
            if automationhat.input[self.state_pin].read() == GARAGE_DOOR_CLOSED:
                return 1
            else:
                return 0
        except Exception as e:
            logger.error(f"Error reading garage door state: {e}")
            raise  # Re-raise the exception to be handled by the caller


    @state.setter
    def state(self, value):
        """
        Raises an exception because the state of the garage door is read-only.
        """
        raise AttributeError("Garage door state is read-only.")


def main():
    """
    Main function to control the garage door.
    """

    try:
        garage_door = GarageDoor()
    except Exception as e:
        logger.critical(f"Failed to initialize garage door: {e}")
        sys.exit(1)

    try:
        while True:
            print("Current state: %s" % garage_door.state)
            action = input("Enter command (open, close, trigger, exit): ")

            if action == "open":
                if garage_door.state == GARAGE_DOOR_CLOSED:
                    garage_door.trigger()
                else:
                    print("Garage door is already open.")
            elif action == "close":
                if garage_door.state == GARAGE_DOOR_OPEN:
                    garage_door.trigger()
                else:
                    print("Garage door is already closed.")
            elif action == "trigger":
                garage_door.trigger()
            elif action == "exit":
                break
            else:
                print("Invalid command.")

    except KeyboardInterrupt:
        logger.info("Exiting program due to keyboard interrupt.")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        automationhat.relay.off()  # Ensure relay is off on exit
        logger.info("Garage door control application finished.")


if __name__ == "__main__":
    main()

