# http relay controller for a Raspberry Pi using a Flask server
# A relay module switches power to a device via a GPIO output pin
# This server listens for HTTP POST requests to toggle the relay state
# A signal handler cleans up GPIO resources on shutdown
from gpiozero import OutputDevice
from flask import Flask, Response, request
import RPi.GPIO as GPIO
import signal
import sys

# GPIO pin connected to the relay module (BCM numbering)
RELAY_PIN = 23
SERVER_PORT = 5000
app = Flask(__name__)
relay_device = None

def initialize_relay():
    """Initialize the relay output device on the specified GPIO pin."""
    # Use BCM numbering and start the relay in the OFF state
    GPIO.setmode(GPIO.BCM)
    relay_device = OutputDevice(RELAY_PIN, active_high=True, initial_value=False)

def handle_relay_request():
    """Handle a POST request to toggle the relay state."""
    # Expect a JSON body with a 'state' key: 'on' or 'off'
    if request.method == 'POST' and request.is_json:
        payload = request.get_json()
        if 'state' in payload:
            target_state = payload['state'].lower()
            if target_state == 'on':
                relay_device.on()
                return Response({'status': 'Relay state changed'}, 200)
            elif target_state == 'off':
                relay_device.off()
                return Response({'status': 'Relay state changed'}, 200)
    return Response({'error': 'Invalid request'}, 400)

@app.route('/relay', methods=['POST'])
def relay_endpoint():
    """Flask route for the relay control endpoint."""
    return handle_relay_request()

def signal_handler(sig, frame):
    """Release GPIO resources on program termination."""
    # Clean up GPIO pins before exiting
    if relay_device is not None:
        relay_device.close()
    GPIO.cleanup()
    sys.exit(0)

if __name__ == '__main__':
    initialize_relay()
    signal.signal(signal.SIGINT, signal_handler)
    app.run(host='0.0.0.0', port=SERVER_PORT)

