import smbus2
import contextlib

@contextlib.contextmanager
def i2c_device(address, bus_number=1):
    """Context manager for I2C device, ensuring bus is closed."""
    try:
        bus = smbus2.SMBus(bus_number)
        yield bus, address
    finally:
        bus.close()

def write_byte(bus, address, register, value):
    """Write a byte to a register."""
    try:
        bus.write_byte_data(address, register, value)
    except (OSError, IOError) as e:
        raise RuntimeError(f"I2C write error: {e}")

def read_byte(bus, address, register):
    """Read a byte from a register."""
    try:
        return bus.read_byte_data(address, register)
    except (OSError, IOError) as e:
        raise RuntimeError(f"I2C read error: {e}")


class I2CDevice:
    """Helper class for I2C communication with a device."""

    def __init__(self, address, bus_number=1):
        self.address = address
        self.bus_number = bus_number

    def __enter__(self):
        """Enter the context, open the bus."""
        with i2c_device(self.address, self.bus_number) as (bus, address):
            self.bus = bus
            self.address = address
            return self

    def __exit__(self, exc_type, exc_val, exc_tb):
        """Exit the context, close the bus."""
        self.bus.close()

    def write_byte(self, register, value):
        """Write a byte to a register."""
        write_byte(self.bus, self.address, register, value)

    def read_byte(self, register):
        """Read a byte from a register."""
        return read_byte(self.bus, self.address, register)

