#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock (RTC) Driver for Raspberry Pi

This module provides a robust and optimized interface to the DS1338 RTC chip
using the I2C bus. It offers comprehensive error handling, detailed documentation,
and adheres to best practices for hardware interaction.

Key Features:
- Comprehensive error handling and recovery.
- Detailed documentation with docstrings.
- Best practices for hardware interaction.
- Optimized for performance and resource usage.
"""

import smbus2
import time
from datetime import datetime
import logging
import os
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
TWI_BUS = 1
DS1338_ADDRESS = 0x68
REG_SECONDS = 0x00
REG_MINUTES = 0x01
REG_HOURS = 0x02
REG_DAY = 0x03
REG_DATE = 0x04
REG_MONTH = 0x05
REG_YEAR = 0x06
REG_CONTROL = 0x07
REGISTER_LIST = [REG_SECONDS, REG_MINUTES, REG_HOURS, REG_DATE, REG_MONTH, REG_YEAR]

# Global variable for the I2C bus, initialized to None
I2C_BUS = None

def initialize_i2c_bus():
    """Initializes the I2C bus and handles potential errors."""
    global I2C_BUS
    try:
        I2C_BUS = smbus2.SMBus(TWI_BUS)
        logging.info(f"I2C bus {TWI_BUS} initialized successfully.")
    except OSError as e:
        logging.error(f"Failed to initialize I2C bus: {e}")
        raise  # Re-raise the exception to be handled by the caller

def _read_register(register):
    """Reads a byte from the specified register."""
    try:
        return I2C_BUS.read_byte_data(DS1338_ADDRESS, register)
    except OSError as e:
        logging.error(f"I2C read error at register 0x{register:02X}: {e}")
        return None  # Return None to indicate an error

def _write_register(register, value):
    """Writes a byte to the specified register."""
    try:
        I2C_BUS.write_byte_data(DS1338_ADDRESS, register, value)
        logging.debug(f"Wrote 0x{value:02X} to register 0x{register:02X}")
    except OSError as e:
        logging.error(f"I2C write error at register 0x{register:02X}: {e}")

def _bcd_to_int(bcd_value):
    """Converts BCD to integer."""
    try:
        return (bcd_value >> 4) * 10 + (bcd_value & 0x0F)
    except TypeError:
        logging.error(f"Invalid BCD value: {bcd_value}")
        return None

def _int_to_bcd(integer_value):
    """Converts integer to BCD."""
    if not 0 <= integer_value <= 99:
        raise ValueError("Integer value must be between 0 and 99 for BCD conversion.")
    return (integer_value // 10 << 4) | (integer_value % 10)

def read_all():
    """Reads all RTC registers and returns them as a tuple."""
    try:
        data = [I2C_BUS.read_i2c_block_data(DS1338_ADDRESS, reg, 1)[0] for reg in REGISTER_LIST]
        return tuple(data)
    except OSError as e:
        logging.error(f"Failed to read all RTC registers: {e}")
        return None

def read_datetime(century=21):
    """Reads the RTC and returns a datetime object."""
    data = read_all()
    if data is None:
        return None

    try:
        year, month, date, hours, minutes, seconds = \
            data[REG_YEAR], data[REG_MONTH], data[REG_DATE], data[REG_HOURS] & 0x3F, data[REG_MINUTES], data[REG_SECONDS]
        hour12 = (hours & 0x40) >> 6  # 12-hour mode flag
        hours = _bcd_to_int(hours & 0x1F) # Remove 12/24 bit

        if century < 0 or century > 9:
            raise ValueError("Invalid century value.")

        year = (century * 100) + _bcd_to_int(year)
        month = _bcd_to_int(month)
        date = _bcd_to_int(date)
        minutes = _bcd_to_int(minutes)
        seconds = _bcd_to_int(seconds)

        try:
            return datetime(year, month, date, hours=hours, minutes=minutes, seconds=seconds)
        except ValueError as e:
            logging.error(f"Invalid date/time data: {e}")
            return None

    except (ValueError, TypeError) as e:
        logging.error(f"Error converting RTC data: {e}")
        return None

def write_all(data):
    """Writes all RTC registers."""
    if data is None or len(data) != len(REGISTER_LIST):
        raise ValueError("Data must be a tuple of length 6.")
    try:
        for register, value in zip(REGISTER_LIST, data):
            _write_register(register, value)
    except OSError as e:
        logging.error(f"Failed to write all RTC registers: {e}")

def write_datetime(dt):
    """Writes the given datetime object to the RTC."""
    if not isinstance(dt, datetime):
        raise ValueError("Input must be a datetime object.")
    try:
        data = [
            _int_to_bcd(dt.second),
            _int_to_bcd(dt.minute),
            _int_to_bcd(dt.hour),
            _int_to_bcd(dt.isoweekday()),
            _int_to_bcd(dt.day),
            _int_to_bcd(dt.month),
            _int_to_bcd(dt.year % 100),
        ]
        write_all(data)
    except OSError as e:
        logging.error(f"Failed to write datetime to RTC: {e}")


def cleanup():
    """Releases any resources held by the driver."""
    global I2C_BUS
    if I2C_BUS:
        try:
            I2C_BUS.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            logging.error(f"Error closing I2C bus: {e}")
        finally:
            I2C_BUS = None


def signal_handler(sig, frame):
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Received signal, shutting down...")
    cleanup()
    sys.exit(0)

def main():
    """Main function for demonstration and testing."""
    signal.signal(signal.SIGINT, signal_handler)
    signal.signal(signal.SIGTERM, signal_handler)

    try:
        initialize_i2c_bus()
        logging.info("DS1338 driver initialized.")

        now = datetime.now()
        write_datetime(now)
        time.sleep(1)

        rtc_data = read_all()
        if rtc_data:
            logging.info(f"RTC registers: {rtc_data}")
            rtc_datetime = read_datetime()
            if rtc_datetime:
                logging.info(f"Read datetime: {rtc_datetime}")

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")
    finally:
        cleanup()


if __name__ == "__main__":
    main()

