# -*- coding: utf-8 -*-
"""
Web API for an in-memory data store on a Raspberry Pi, with a serial
instrument gateway for remote control of a lab device.

This file implements a Flask web server that exposes routes for listing,
retrieving, creating, and updating data items.  It also wraps a serial
communication layer for a USB-serial instrument, handling reads and writes
with a 1 second timeout.
"""

import json
import logging
import threading
import time
import signal
import sys
from typing import Dict, List, Tuple, Union

from flask import Flask, Response, request, jsonify, abort
import serial

# Configure logging for the web API
logging.basicConfig(level=logging.INFO,
                    format='%(asctime)s - %(levelname)s - %(message)s')

app = Flask(__name__)
DATA_STORE: List[Dict[str, Union[int, str, bool]]] = [
    {'id': 1, 'name': 'Item One', 'done': False},
    {'id': 2, 'name': 'Item Two', 'done': False},
]
NEXT_ID: int = 2 + DATA_STORE[-1].get('id', 0)


class SerialCommunicator:
    """Encapsulates serial communication with a USB instrument."""

    def __init__(self, port: str = '/dev/ttyUSB0', baudrate: int = 9600,
                 timeout: float = 1.0):
        """Initializes the serial port connection."""
        self.port = port
        self.baudrate = baudrate
        self.timeout = timeout
        self.ser = None
        self.lock = threading.Lock()  # Protect shared resources

    def open(self) -> bool:
        """Opens the serial port, handling potential exceptions."""
        try:
            with self.lock:
                self.ser = serial.Serial(self.port, self.baudrate, timeout=self.timeout)
            logging.info(f"Serial port {self.port} opened successfully.")
            return True
        except serial.SerialException as e:
            logging.error(f"Failed to open serial port {self.port}: {e}")
            return False

    def close(self) -> None:
        """Closes the serial port, if open."""
        try:
            with self.lock:
                if self.ser and self.ser.is_open:
                    self.ser.close()
                    logging.info(f"Serial port {self.port} closed.")
        except Exception as e:
            logging.error(f"Error closing serial port: {e}")

    def send(self, cmd: str) -> Union[bytes, None]:
        """Sends a command over the serial port, returning the response."""
        if not self.ser or not self.ser.is_open:
            logging.error("Serial port not open.")
            return None
        try:
            with self.lock:
                self.ser.write(cmd.encode('ascii'))
                response = self.ser.readline()
                return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None

    def receive_line(self) -> Union[str, None]:
        """Reads a line from the serial port, handling timeouts."""
        if not self.ser or not self.ser.is_open:
            logging.error("Serial port not open.")
            return None
        try:
            with self.lock:
                response = self.ser.readline().decode('ascii', errors='ignore').strip()
                return response
        except serial.SerialException as e:
            logging.error(f"Serial communication error: {e}")
            return None
        except Exception as e:
            logging.error(f"Unexpected error reading serial port: {e}")
            return None


def get_serial_communicator() -> SerialCommunicator:
    """Returns the global serial communicator instance."""
    return SerialCommunicator()


@app.route('/version', methods=['GET'])
def get_version() -> Response:
    """Queries the instrument for its firmware version."""
    serial_comm = get_serial_communicator()
    if not serial_comm.open():
        return Response("Error: Could not open serial port.\n", mimetype='text/plain', status=500)

    try:
        response_bytes = serial_comm.send('*IDN?\n')
        if response_bytes:
            response_text = response_bytes.decode('ascii', errors='ignore').strip()
            parts = response_text.split(',')
            if len(parts) == 4:
                return Response(parts[3] + '\n', mimetype='text/plain', status=200)
            else:
                logging.warning(f"Unexpected instrument response format: {response_text}")
                return Response("Error: Invalid instrument response format.\n",
                               mimetype='text/plain', status=500)
        else:
            logging.warning("No response received from the instrument.")
            return Response("Error: No response from instrument.\n",
                           mimetype='text/plain', status=504)
    except Exception as e:
        logging.error(f"Failed to get version: {e}")
        return Response(f"Error: {e}\n", mimetype='text/plain', status=500)
    finally:
        serial_comm.close()


@app.route('/data', methods=['GET'])
def get_all() -> Response:
    """Returns the entire data store as JSON."""
    return Response(json.dumps(DATA_STORE), mimetype='application/json')


@app.route('/data/<int:item_id>', methods=['GET'])
def get_by_id(item_id: int) -> Union[Response, jsonify]:
    """Retrieves a single item by its ID."""
    item = next((item for item in DATA_STORE if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        abort(404)


@app.route('/data', methods=['POST'])
def create() -> Union[Response, jsonify]:
    """Creates a new data item from a JSON payload."""
    try:
        data = request.get_json()
        if not data:
            abort(400)

        name = data.get('name')
        if not name:
            abort(400, description="Missing 'name' field in JSON payload.")

        item = {
            'id': NEXT_ID,
            'name': name,
            'done': bool(data.get('done', False)),
        }
        DATA_STORE.append(item)
        NEXT_ID += 1
        return jsonify(item), 201

    except ValueError:
        abort(400, description="Invalid JSON format in request body.")


@app.route('/data/<int:item_id>', methods=['PUT'])
def update(item_id: int) -> Union[Response, jsonify, abort]:
    """Updates an existing data item by its ID."""
    global DATA_STORE
    try:
        data = request.get_json()
        if not data:
            abort(400)

        name = data.get('name')
        done = data.get('done')

        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if not item:
            abort(404)

        if name is not None:
            item['name'] = name
        if done is not None:
            item['done'] = bool(done)

        DATA_STORE = [item] + [i for i in DATA_STORE if i['id'] != item_id]
        return jsonify(item)

    except ValueError:
        abort(400, description="Invalid JSON format in request body.")


@app.route('/data/<int:item_id>', methods=['DELETE'])
def delete(item_id: int) -> Response:
    """Deletes an existing data item by its ID."""
    global DATA_STORE
    try:
        item = next((item for item in DATA_STORE if item['id'] == item_id), None)
        if item:
            DATA_STORE = [i for i in DATA_STORE if i['id'] != item_id]
            return Response(status=204)
        else:
            abort(404)
    except Exception as e:
        logging.error(f"Failed to delete item {item_id}: {e}")
        return Response(f"Error: {e}\n", mimetype='text/plain', status=500)


def shutdown_server(signum: int, frame: object) -> None:
    """Handles SIGINT and SIGTERM signals for graceful shutdown."""
    logging.info("Shutting down server...")
    app.close()
    sys.exit(0)


if __name__ == '__main__':
    # Register signal handlers for graceful shutdown
    signal.signal(signal.SIGINT, shutdown_server)
    signal.signal(signal.SIGTERM, shutdown_server)

    # Start the Flask development server
    app.run(host='0.0.0.0', port=5000, debug=False)

