from flask import Flask, Response, request, jsonify, abort
import json
import time
import serial
import logging

# Configure logging for the Raspberry Pi web service
logging.basicConfig(level=logging.INFO)
app = Flask(__name__)
store = [{"id": 1, "name": "item-1", "done": False}, {"id": 2, "name": "item-2", "done": False}]

@app.route('/version')
def version():
    """Read and return the SCPI instrument version over serial."""
    # Open the serial port and query the instrument
    try:
        with serial.Serial('/dev/ttyUSB0', 9600, timeout=1) as ser:
            ser.write(b'*IDN?\n')
            time.sleep(0.1)
            version_text = ser.read(100).decode('utf-8', errors='ignore')
        # Return the version text as HTML with line breaks
        return Response('<html><body>{}</body></html>'.format(
            version_text.replace('\n', '<br>')), mimetype='text/html')
    except serial.SerialException:
        # Report a failed serial connection to the user
        return Response('<html><body>Serial port unavailable</body></html>',
                        mimetype='text/html', status=503)

@app.route('/getdata')
def getdata():
    """Return the current in-memory data store as JSON."""
    return jsonify(store)

@app.route('/getset/<int:item_id>')
def getset(item_id):
    """Return a single item from the store by id or 404."""
    item = next((item for item in store if item['id'] == item_id), None)
    if item is None:
        abort(404)
    return jsonify(item)

@app.route('/getpost/<int:item_id>/<name>')
def getpost(item_id, name):
    """Append a new item to the store and return the updated list."""
    # Build the new item and append it to the in-memory store
    new_item = {
        "id": item_id,
        "name": name,
        "done": False,
    }
    store.append(new_item)
    return jsonify(store)

@app.route('/postjson', methods=['POST', 'GET'])
def postjson():
    """Accept JSON data via POST or GET and append it to the store."""
    try:
        if request.method == 'POST':
            if 'application/json' in request.headers.get('Content-Type', ''):
                data = request.get_json()
            else:
                data = request.form.to_dict()
        else:
            data = request.values.to_dict()
        item = {
            "id": store[-1]['id'] + 1 if store else 1,
            "name": data.get('name', ''),
            "done": data.get('done', False),
        }
        store.append(item)
        return jsonify(store)
    except (KeyError, ValueError):
        abort(400)

if __name__ == '__main__':
    app.run(debug=True, host='0.0.0.0')

