import serial
import time

# Define the Bluetooth device's serial port and baud rate
bluetooth_port = "/dev/rfcomm4"
bluetooth_baudrate = 38400

def initialize_bluetooth():
    """Establishes a serial connection to the Bluetooth device."""
    try:
        bluetooth_connection = serial.Serial(bluetooth_port, bluetooth_baudrate)
        return bluetooth_connection
    except serial.SerialException as e:
        print(f"Error opening Bluetooth port: {e}")
        return None

def send_command(connection, command_text):
    """Sends a command to the Bluetooth device."""
    try:
        full_command = 'X' + command_text + '\n'
        connection.write(full_command.encode())
        print(f"Sent: {full_command.strip()}")
    except serial.SerialException as e:
        print(f"Error sending command: {e}")

def main():
    """Main function to handle user input and send commands."""
    bluetooth_connection = initialize_bluetooth()

    if bluetooth_connection is None:
        print("Failed to initialize Bluetooth connection. Exiting.")
        return

    try:
        while True:
            user_command = input("Enter command (or 'exit'): ")
            if user_command.lower() == 'exit':
                break
            send_command(bluetooth_connection, user_command)
            time.sleep(0.1)  # Small delay to prevent overwhelming the device
    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        if bluetooth_connection and bluetooth_connection.is_open:
            bluetooth_connection.close()
            print("Bluetooth connection closed.")

if __name__ == "__main__":
    main()

